  1	import { useCallback, useEffect, useMemo, useRef, useState } from "react";
  2	import { EditorContent, useEditor } from "@tiptap/react";
  3	import { TextSelection } from "@tiptap/pm/state";
  4	import type { EditorView } from "@tiptap/pm/view";
  5	import StarterKit from "@tiptap/starter-kit";
  6	import Placeholder from "@tiptap/extension-placeholder";
  7	import { joinFrontmatter, splitFrontmatter } from "@typenotes/shared/frontmatter";
  8	import { stripInlineAnnotationMetadata } from "@typenotes/shared/annotation-metadata";
  9	import {
 10	  appendRawLensBackmatterBlock,
 11	  splitLensBackmatterBlock,
 12	} from "@typenotes/shared/lens-backmatter";
 13	import { NOTE_EDITOR_ENTER_INSERT_EVENT } from "../lib/editor-events";
 14	import { htmlToMarkdown, markdownToHtml } from "../lib/markdown-editor";
 15	import { useAppearance } from "@/app/state/appearance-store";
 16	
 17	type NoteEditorProps = {
 18	  documentKey: string | null;
 19	  markdown: string;
 20	  onChange: (markdown: string) => void;
 21	};
 22	
 23	type VimMode = "normal" | "insert" | "visual";
 24	
 25	type VimCursorRect = {
 26	  left: number;
 27	  top: number;
 28	  width: number;
 29	  height: number;
 30	};
 31	
 32	const VIM_JUMP_LINES = 10;
 33	
 34	const clampDocumentPosition = (view: EditorView, position: number) =>
 35	  Math.max(1, Math.min(view.state.doc.content.size, position));
 36	
 37	const getAdjacentTextblockVerticalPosition = (
 38	  view: EditorView,
 39	  position: number,
 40	  direction: -1 | 1
 41	) => {
 42	  try {
 43	    const resolved = view.state.doc.resolve(position);
 44	    if (!view.endOfTextblock(direction > 0 ? "down" : "up")) {
 45	      return null;
 46	    }
 47	    const boundary = direction > 0 ? resolved.after() : resolved.before();
 48	    const adjacent = TextSelection.near(
 49	      view.state.doc.resolve(boundary),
 50	      direction
 51	    );
 52	    if (resolved.sameParent(adjacent.$head)) {
 53	      return null;
 54	    }
 55	
 56	    // Once the cursor is at the first/last visual line of a text block, move
 57	    // through the document structure. Hit-testing coordinates at a paragraph
 58	    // boundary is asymmetric in ProseMirror: moving down usually resolves to
 59	    // the next block, while moving up can resolve back into the current one.
 60	    // The parent offset retains Vim's desired column and naturally becomes 0
 61	    // for an empty paragraph.
 62	    return (
 63	      adjacent.$head.start() +
 64	      Math.min(resolved.parentOffset, adjacent.$head.parent.content.size)
 65	    );
 66	  } catch {
 67	    // Fall through to geometry-based movement at unusual nested boundaries.
 68	  }
 69	  return null;
 70	};
 71	
 72	const getVerticalPosition = (
 73	  view: EditorView,
 74	  position: number,
 75	  direction: -1 | 1,
 76	  lineCount: number,
 77	  goalLeft: number
 78	) => {
 79	  try {
 80	    // side=1 is important at the first character of a line/block. Without it,
 81	    // ProseMirror may measure the same document position as the end of the
 82	    // previous line, which makes `k` jump to that line's final character.
 83	    const coords = view.coordsAtPos(position, 1);
 84	    const measuredLineHeight = coords.bottom - coords.top;
 85	    const computedLineHeight = Number.parseFloat(
 86	      window.getComputedStyle(view.dom).lineHeight
 87	    );
 88	    const lineHeight =
 89	      measuredLineHeight > 0
 90	        ? measuredLineHeight
 91	        : Number.isFinite(computedLineHeight)
 92	          ? computedLineHeight
 93	          : 24;
 94	    const startCenter = (coords.top + coords.bottom) / 2;
 95	    const scanStep = Math.max(3, lineHeight / 4);
 96	    const maxDistance = lineHeight * (lineCount * 4 + 4);
 97	    let lastLineCenter = startCenter;
 98	    let linesMoved = 0;
 99	    let lastPosition: number | null = null;
100	
101	    // Scan through layout space instead of assuming adjacent text blocks have
102	    // no margin. This avoids resolving a point in the gap between paragraphs
103	    // to the end of the previous line.
104	    for (let distance = scanStep; distance <= maxDistance; distance += scanStep) {
105	      const target = view.posAtCoords({
106	        left: goalLeft,
107	        top: startCenter + direction * distance,
108	      });
109	      if (!target) {
110	        continue;
111	      }
112	      const targetCoords = view.coordsAtPos(target.pos, 1);
113	      const targetCenter = (targetCoords.top + targetCoords.bottom) / 2;
114	      const crossedLine =
115	        direction * (targetCenter - lastLineCenter) > Math.max(3, lineHeight * 0.35);
116	      if (!crossedLine) {
117	        continue;
118	      }
119	      linesMoved += 1;
120	      lastLineCenter = targetCenter;
121	      lastPosition = clampDocumentPosition(view, target.pos);
122	      if (linesMoved >= lineCount) {
123	        return lastPosition;
124	      }
125	    }
126	    if (lastPosition !== null) {
127	      return lastPosition;
128	    }
129	  } catch {
130	    // Geometry can be unavailable during a document/layout transition.
131	  }
132	  return direction < 0 ? 1 : view.state.doc.content.size;
133	};
134	
135	const toolbarButton =
136	  "rounded-md border border-transparent px-2 py-1 text-xs font-medium text-[var(--ui-muted)] transition-colors hover:border-[var(--ui-border)] hover:bg-[var(--ui-select)] hover:text-[var(--ui-text)]";
137	
138	const splitEditorMarkdown = (markdown: string) => {
139	  const split = splitFrontmatter(markdown);
140	  const lensSplit = splitLensBackmatterBlock(split.body);
141	  return {
142	    frontmatterBlock: split.frontmatterBlock,
143	    backmatterBlock: lensSplit.rawBlock,
144	    body: stripInlineAnnotationMetadata(lensSplit.content),
145	  };
146	};
147	
148	export function NoteEditor({ documentKey, markdown, onChange }: NoteEditorProps) {
149	  const showVimModeIndicator = useAppearance(
150	    (state) => state.showVimModeIndicator
151	  );
152	  const [vimMode, setVimModeState] = useState<VimMode>("normal");
153	  const [vimCursorRect, setVimCursorRect] = useState<VimCursorRect | null>(null);
154	  const vimModeRef = useRef<VimMode>("normal");
155	  const visualAnchorRef = useRef<number | null>(null);
156	  const verticalGoalLeftRef = useRef<number | null>(null);
157	  const isVerticalMotionRef = useRef(false);
158	  const lastDocumentKeyRef = useRef<string | null>(null);
159	  const pendingInsertDocumentKeyRef = useRef<string | null>(null);
160	  const isSyncing = useRef(false);
161	  const latestMarkdown = useRef(markdown);
162	  const scrollRef = useRef<HTMLDivElement | null>(null);
163	  const initialContentRef = useRef(splitEditorMarkdown(markdown));
164	  const frontmatterRef = useRef<string | null>(initialContentRef.current.frontmatterBlock);
165	  const backmatterRef = useRef<string | null>(initialContentRef.current.backmatterBlock);
166	
167	  const setVimMode = useCallback((mode: VimMode) => {
168	    vimModeRef.current = mode;
169	    visualAnchorRef.current = null;
170	    setVimModeState(mode);
171	  }, []);
172	
173	  const updateVimCursor = useCallback((view: EditorView) => {
174	    const scrollElement = scrollRef.current;
175	    if (!scrollElement || !view.hasFocus()) {
176	      setVimCursorRect(null);
177	      return;
178	    }
179	    try {
180	      const position = view.state.selection.head;
181	      const coords = view.coordsAtPos(position, 1);
182	      const nextPosition = Math.min(view.state.doc.content.size, position + 1);
183	      const nextCoords = view.coordsAtPos(nextPosition, -1);
184	      const computedStyle = window.getComputedStyle(view.dom);
185	      const fontSize = Number.parseFloat(computedStyle.fontSize) || 16;
186	      const measuredWidth =
187	        Math.abs(nextCoords.top - coords.top) < 2
188	          ? nextCoords.left - coords.left
189	          : 0;
190	      const scrollRect = scrollElement.getBoundingClientRect();
191	      const nextRect = {
192	        left: coords.left - scrollRect.left + scrollElement.scrollLeft,
193	        top: coords.top - scrollRect.top + scrollElement.scrollTop,
194	        width: Math.max(7, Math.min(fontSize * 1.2, measuredWidth || fontSize * 0.62)),
195	        height: Math.max(14, coords.bottom - coords.top),
196	      };
197	      setVimCursorRect((current) =>
198	        current &&
199	        Math.abs(current.left - nextRect.left) < 0.5 &&
200	        Math.abs(current.top - nextRect.top) < 0.5 &&
201	        Math.abs(current.width - nextRect.width) < 0.5 &&
202	        Math.abs(current.height - nextRect.height) < 0.5
203	          ? current
204	          : nextRect
205	      );
206	    } catch {
207	      setVimCursorRect(null);
208	    }
209	  }, []);
210	
211	  const moveVimSelection = useCallback(
212	    (view: EditorView, targetPosition: number) => {
213	      const target = clampDocumentPosition(view, targetPosition);
214	      const normalizedHead = TextSelection.near(
215	        view.state.doc.resolve(target)
216	      ).head;
217	      const selection =
218	        vimModeRef.current === "visual"
219	          ? TextSelection.create(
220	              view.state.doc,
221	              visualAnchorRef.current ?? view.state.selection.anchor,
222	              normalizedHead
223	            )
224	          : TextSelection.near(view.state.doc.resolve(normalizedHead));
225	      view.dispatch(view.state.tr.setSelection(selection).scrollIntoView());
226	    },
227	    []
228	  );
229	
230	  const handleVimKeyDown = useCallback(
231	    (view: EditorView, event: KeyboardEvent) => {
232	      const mode = vimModeRef.current;
233	      if (event.key === "Escape") {
234	        event.preventDefault();
235	        event.stopPropagation();
236	        const head = view.state.selection.head;
237	        verticalGoalLeftRef.current = null;
238	        setVimMode("normal");
239	        moveVimSelection(view, head);
240	        return true;
241	      }
242	      if (mode === "insert") {
243	        return false;
244	      }
245	      if (event.metaKey || event.altKey) {
246	        return false;
247	      }
248	
249	      const code = event.code;
250	      const direction = code === "KeyJ" ? 1 : code === "KeyK" ? -1 : null;
251	      if (direction) {
252	        event.preventDefault();
253	        event.stopPropagation();
254	        const lineCount = event.ctrlKey ? VIM_JUMP_LINES : 1;
255	        const currentCoords = view.coordsAtPos(view.state.selection.head, 1);
256	        const goalLeft =
257	          verticalGoalLeftRef.current ?? currentCoords.left + 1;
258	        verticalGoalLeftRef.current = goalLeft;
259	        isVerticalMotionRef.current = true;
260	        const adjacentTextblockTarget =
261	          lineCount === 1
262	            ? getAdjacentTextblockVerticalPosition(
263	                view,
264	                view.state.selection.head,
265	                direction
266	              )
267	            : null;
268	        moveVimSelection(
269	          view,
270	          adjacentTextblockTarget ??
271	            getVerticalPosition(
272	              view,
273	              view.state.selection.head,
274	              direction,
275	              lineCount,
276	              goalLeft
277	            )
278	        );
279	        isVerticalMotionRef.current = false;
280	        return true;
281	      }
282	      if (event.ctrlKey) {
283	        return false;
284	      }
285	      if (code === "KeyH" || code === "KeyL") {
286	        event.preventDefault();
287	        event.stopPropagation();
288	        verticalGoalLeftRef.current = null;
289	        moveVimSelection(
290	          view,
291	          view.state.selection.head + (code === "KeyH" ? -1 : 1)
292	        );
293	        return true;
294	      }
295	      if (code === "KeyV") {
296	        event.preventDefault();
297	        event.stopPropagation();
298	        verticalGoalLeftRef.current = null;
299	        if (mode === "visual") {
300	          const head = view.state.selection.head;
301	          setVimMode("normal");
302	          moveVimSelection(view, head);
303	        } else {
304	          visualAnchorRef.current = view.state.selection.head;
305	          vimModeRef.current = "visual";
306	          setVimModeState("visual");
307	        }
308	        return true;
309	      }
310	      if (code === "KeyI" || code === "KeyA") {
311	        event.preventDefault();
312	        event.stopPropagation();
313	        verticalGoalLeftRef.current = null;
314	        if (code === "KeyA") {
315	          moveVimSelection(view, view.state.selection.head + 1);
316	        }
317	        setVimMode("insert");
318	        return true;
319	      }
320	
321	      // Normal/Visual modes are navigation-only. Block printable text and
322	      // destructive editing until the user explicitly enters Insert mode.
323	      if (
324	        event.key.length === 1 ||
325	        event.key === "Enter" ||
326	        event.key === "Backspace" ||
327	        event.key === "Delete"
328	      ) {
329	        event.preventDefault();
330	        event.stopPropagation();
331	        return true;
332	      }
333	      return false;
334	    },
335	    [moveVimSelection, setVimMode]
336	  );
337	
338	  const keepCaretBreathingRoom = (currentEditor: NonNullable<ReturnType<typeof useEditor>>) => {
339	    const scrollEl = scrollRef.current;
340	    if (!scrollEl) {
341	      return;
342	    }
343	    const position = currentEditor.state.selection.$anchor.pos;
344	    let coords: { top: number; bottom: number };
345	    try {
346	      coords = currentEditor.view.coordsAtPos(position);
347	    } catch {
348	      return;
349	    }
350	    const rect = scrollEl.getBoundingClientRect();
351	    const bottomLimit = rect.bottom - rect.height * 0.2;
352	    if (coords.bottom <= bottomLimit) {
353	      return;
354	    }
355	    const delta = coords.bottom - bottomLimit;
356	    const maxScrollTop = scrollEl.scrollHeight - scrollEl.clientHeight;
357	    scrollEl.scrollTop = Math.min(maxScrollTop, scrollEl.scrollTop + delta);
358	  };
359	
360	  const extensions = useMemo(
361	    () => [
362	      StarterKit.configure({
363	        heading: { levels: [1, 2, 3] },
364	      }),
365	      Placeholder.configure({
366	        placeholder: "What's on your mind?",
367	      }),
368	    ],
369	    []
370	  );
371	
372	  const editor = useEditor({
373	    extensions,
374	    autofocus: false,
375	    enableInputRules: false,
376	    content: markdownToHtml(initialContentRef.current.body),
377	    editorProps: {
378	      attributes: {
379	        class: "tiptap-content",
380	        "aria-label": "Note editor",
381	      },
382	      handleKeyDown: handleVimKeyDown,
383	      handleTextInput: () => vimModeRef.current !== "insert",
384	      handlePaste: () => vimModeRef.current !== "insert",
385	    },
386	    onFocus: ({ editor: currentEditor }) => {
387	      setVimMode("normal");
388	      requestAnimationFrame(() => updateVimCursor(currentEditor.view));
389	    },
390	    onBlur: () => setVimCursorRect(null),
391	    onSelectionUpdate: ({ editor: currentEditor }) => {
392	      if (!isVerticalMotionRef.current) {
393	        verticalGoalLeftRef.current = null;
394	      }
395	      updateVimCursor(currentEditor.view);
396	    },
397	    onUpdate: ({ editor: currentEditor }) => {
398	      if (isSyncing.current) {
399	        return;
400	      }
401	      const nextBodyMarkdown = htmlToMarkdown(currentEditor.getHTML());
402	      const frontmatterJoined = joinFrontmatter(frontmatterRef.current, nextBodyMarkdown);
403	      const nextMarkdown = appendRawLensBackmatterBlock(
404	        frontmatterJoined,
405	        backmatterRef.current
406	      );
407	      latestMarkdown.current = nextMarkdown;
408	      onChange(nextMarkdown);
409	      requestAnimationFrame(() => keepCaretBreathingRoom(currentEditor));
410	    },
411	  });
412	
413	  useEffect(() => {
414	    if (!editor) {
415	      return;
416	    }
417	    if (markdown === latestMarkdown.current) {
418	      return;
419	    }
420	    const incoming = splitEditorMarkdown(markdown);
421	    frontmatterRef.current = incoming.frontmatterBlock;
422	    backmatterRef.current = incoming.backmatterBlock;
423	    const currentBodyMarkdown = htmlToMarkdown(editor.getHTML());
424	    if (currentBodyMarkdown === incoming.body) {
425	      latestMarkdown.current = markdown;
426	      return;
427	    }
428	    isSyncing.current = true;
429	    editor.commands.setContent(markdownToHtml(incoming.body), { emitUpdate: false });
430	    isSyncing.current = false;
431	    latestMarkdown.current = markdown;
432	  }, [editor, markdown]);
433	
434	  useEffect(() => {
435	    const handleInsertRequest = (event: Event) => {
436	      const notePath = (event as CustomEvent<string>).detail;
437	      if (notePath) {
438	        pendingInsertDocumentKeyRef.current = notePath;
439	      }
440	    };
441	    window.addEventListener(NOTE_EDITOR_ENTER_INSERT_EVENT, handleInsertRequest);
442	    return () =>
443	      window.removeEventListener(
444	        NOTE_EDITOR_ENTER_INSERT_EVENT,
445	        handleInsertRequest
446	      );
447	  }, []);
448	
449	  useEffect(() => {
450	    if (!editor || !documentKey || documentKey === lastDocumentKeyRef.current) {
451	      return;
452	    }
453	    lastDocumentKeyRef.current = documentKey;
454	    const shouldEnterInsertMode =
455	      pendingInsertDocumentKeyRef.current === documentKey;
456	    if (shouldEnterInsertMode) {
457	      pendingInsertDocumentKeyRef.current = null;
458	    }
459	
460	    // Promoting a focused draft to a persisted note is not navigation: keep
461	    // the insertion point so background note creation never interrupts typing.
462	    if (
463	      !shouldEnterInsertMode &&
464	      editor.view.hasFocus() &&
465	      vimModeRef.current === "insert"
466	    ) {
467	      return;
468	    }
469	
470	    verticalGoalLeftRef.current = null;
471	    setVimMode(shouldEnterInsertMode ? "insert" : "normal");
472	    editor.view.dispatch(
473	      editor.view.state.tr
474	        .setSelection(TextSelection.atStart(editor.view.state.doc))
475	        .scrollIntoView()
476	    );
477	    if (scrollRef.current) {
478	      scrollRef.current.scrollTop = 0;
479	      scrollRef.current.scrollLeft = 0;
480	    }
481	    requestAnimationFrame(() => {
482	      if (shouldEnterInsertMode) {
483	        editor.commands.focus("start");
484	      } else {
485	        updateVimCursor(editor.view);
486	      }
487	    });
488	  }, [documentKey, editor, setVimMode, updateVimCursor]);
489	
490	  useEffect(() => {
491	    if (!editor || !scrollRef.current) {
492	      return;
493	    }
