546	          type="button"
547	          className={`${toolbarButton}${editor.isActive("blockquote") ? " is-active" : ""}`}
548	          onClick={() => editor.chain().focus().toggleBlockquote().run()}
549	        >
550	          Quote
551	        </button>
552	        <button
553	          type="button"
554	          className={toolbarButton}
555	          onClick={() => editor.chain().focus().undo().run()}
556	        >
557	          Undo
558	        </button>
559	        <button
560	          type="button"
561	          className={toolbarButton}
562	          onClick={() => editor.chain().focus().redo().run()}
563	        >
564	          Redo
565	        </button>
566	      </div>
567	      <div
568	        className="tiptap-scroll"
569	        ref={(node) => {
570	          scrollRef.current = node;
571	        }}
572	        onClick={() => {
573	          editor.commands.focus();
574	          setVimMode("insert");
575	        }}
576	      >
577	        <EditorContent editor={editor} />
578	        {vimMode !== "insert" && vimCursorRect ? (
579	          <span
580	            className="vim-block-cursor"
581	            aria-hidden="true"
582	            style={vimCursorRect}
583	          />
584	        ) : null}
585	      </div>
586	      {showVimModeIndicator ? (
587	        <div className="vim-mode-indicator" aria-live="polite">
588	          {vimMode.toUpperCase()}
589	        </div>
590	      ) : null}
591	    </div>
592	  );
593	}

