content.content:
  min-height: 34px;
  border: 3px solid transparent;
  border-radius: 999px;
  background: color-mix(in srgb, var(--ui-muted) 45%, transparent);
  background-clip: padding-box;
}

.vim-mode-indicator {
  position: absolute;
  right: 14px;
  bottom: 10px;
  z-index: 2;
  border: 1px solid var(--ui-border);
  border-radius: 5px;
  padding: 3px 6px 2px;
  background: color-mix(in srgb, var(--ui-pane) 92%, transparent);
  color: var(--ui-muted);
  font-family: ui-monospace, "SFMono-Regular", Consolas, monospace;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  line-height: 1;
  pointer-events: none;
  user-select: none;
}

.vim-block-cursor {
  position: absolute;
  z-index: 3;
  box-sizing: border-box;
  border: 0;
  border-radius: 0;
  background: rgb(255 255 255 / 30%);
  mix-blend-mode: normal;
  /* Previous terminal-style cursor; restore these two declarations to make
     the focused glyph reverse color again.
  background: #fff;
  mix-blend-mode: difference;
  */
  pointer-events: none;
}

.tiptap-editor[data-vim-mode="visual"] .vim-block-cursor {
  background: var(--vim-visual-blue);
  mix-blend-mode: screen;
}

.app.theme-light
  .tiptap-editor[data-vim-mode="visual"]
  .vim-block-cursor {
  mix-blend-mode: multiply;
}

.tiptap-editor[data-vim-mode="normal"] .tiptap-content,
.tiptap-editor[data-vim-mode="visual"] .tiptap-content {
  caret-color: transparent;
}

.tiptap-editor[data-vim-mode="insert"] .tiptap-content {
  caret-color: var(--ui-text);
}

.tiptap-editor[data-vim-mode="visual"] .tiptap-content::selection,
.tiptap-editor[data-vim-mode="visual"] .tiptap-content ::selection {
  background: color-mix(in srgb, var(--vim-visual-blue) 42%, transparent);
}

.tiptap-editor[data-vim-mode="insert"] .vim-mode-indicator {
  border-color: color-mix(in srgb, var(--ui-accent) 45%, var(--ui-border));
  color: var(--ui-accent);
}

.tiptap-content {
  min-height: 100%;
  padding: 10px 12px 16px 22px;
  color: var(--ui-text);
  font-size: var(--editor-font-size, 14px);
  line-height: 1.6;
  outline: none;
}

.app.sidebar-collapsed .tiptap-content {
  padding-left: clamp(56px, 20vw, 380px);
}

.tiptap-content p.is-editor-empty:first-child::before {
  content: attr(data-placeholder);
  color: #7a8593;
  font: 400 calc(var(--editor-font-size, 14px) + 1px) / 1.35 "Avenir Next", "SF Pro Text",
    "Segoe UI", "Noto Sans", Arial, sans-serif;
  letter-spacing: 0.01em;
  text-transform: none;
  float: left;
  height: 0;
  pointer-events: none;
}

.tiptap-editor[data-vim-mode="insert"]
  .tiptap-content
  p.is-editor-empty:first-child::before {
  content: none;
}

.tiptap-content p.is-editor-empty:first-child {
  margin: 0;
}

.tiptap-content::after {
  content: "";
  display: block;
  height: 18vh;

