      P: { type: "visualOperator", operator: "p", register: pending.register },
      "~": { type: "visualOperator", operator: "g~", register: pending.register },
      u: { type: "visualOperator", operator: "gu", register: pending.register },
      U: { type: "visualOperator", operator: "gU", register: pending.register },
