    A: "insertLineEnd",
    o: "openBelow",
    O: "openAbove",
    x: "deleteChar",
    X: "deleteCharBefore",
    D: "deleteToLineEnd",
    C: "changeToLineEnd",
    Y: "yankLine",
    s: "substituteChar",
    S: "substituteLine",
    p: "paste",
    P: "pasteBefore",
    u: "undo",
    J: "joinLines",
    "~": "toggleCase",
    v: "visualChar",
    V: "visualLine",
    ".": "repeatChange",
