1	/**
2	 * The React side of Vim mode: mode state, the pending-key buffer, the block
3	 * cursor's geometry, and the `VimHost` that lets `lib/vim/commands` reach
4	 * Tiptap and the layout.
5	 *
6	 * All Vim state that a command reads back within the same keystroke lives in
7	 * refs, not React state — `setMode` has to be visible to the very next line of
8	 * `executeVimCommand`. The `useState` mirrors exist only for rendering.
9	 */
10	
11	import { useCallback, useRef, useState } from "react";
12	import type { Editor } from "@tiptap/react";
13	import { closeHistory } from "@tiptap/pm/history";
14	import type { EditorView } from "@tiptap/pm/view";
