55	export function useVim({ scrollRef }: UseVimOptions) {
56	  const [mode, setModeState] = useState<VimMode>("normal");
57	  const [pendingLabel, setPendingLabel] = useState("");
58	  const [cursorRect, setCursorRect] = useState<VimCursorRect | null>(null);
59	
60	  const editorRef = useRef<Editor | null>(null);
61	  const modeRef = useRef<VimMode>("normal");
62	  const pendingRef = useRef<VimPending>(emptyPending());
63	  const visualAnchorRef = useRef<number | null>(null);
64	  const lastVisualRef = useRef<VimHost["lastVisual"]>(null);
65	  const lastFindRef = useRef<VimFind | null>(null);
