69	  const isVerticalMotionRef = useRef(false);
70	
71	  const attachEditor = useCallback((editor: Editor | null) => {
72	    editorRef.current = editor;
73	  }, []);
74	
75	  const setMode = useCallback((next: VimMode) => {
76	    modeRef.current = next;
77	    setModeState(next);
78	  }, []);
79	
