83	  }, []);
84	
85	  /** Re-measures the block cursor. Cheap enough to run on every selection change. */
86	  const updateCursor = useCallback(
87	    (view: EditorView) => {
88	      const scrollElement = scrollRef.current;
89	      if (!scrollElement || !view.hasFocus()) {
90	        setCursorRect(null);
91	        return;
92	      }
93	      try {
